package com.game_manager.gm.workflow.dto; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.*;
public record WorkflowDefinitionRequest(@NotBlank @Pattern(regexp="[A-Z][A-Z0-9_]{2,59}")String key,@NotBlank @Size(max=120)String name,@NotBlank String initialStep,@NotEmpty List<@Valid Step> steps,@NotEmpty List<@Valid Transition> transitions,boolean enabled){public record Step(@NotBlank String key,@NotBlank String label,@NotBlank String role,@Min(1)@Max(720)int dueHours,@Min(0)@Max(719)int reminderHours,String escalationRole){}public record Transition(@NotBlank String from,@NotBlank String action,@NotBlank String target,@NotNull Boolean reasonRequired){}}
